/* Synced copy of prototypes/frontend-preview/out/spring_path.h (generated by spring.py) - do not edit by hand.
 * Damped spring tables, Q10 (1024 = target). 65 entries over normalised time,
 * linear interpolation between entries. Integer only, no libm.
 *   MOVE  zeta=0.45 omega=13.0 v0=4.0 dur=520ms  (selection bubble x/y/w/h/radius)
 *   PAGE  zeta=0.72 omega=9.0 v0=2.5 dur=460ms  (page slide)
 *   POP   zeta=0.45 omega=12.0 v0=4.0 dur=480ms  (card scale-in)
 *   PULSE zeta=0.28 omega=22.0 dur=520ms (jelly squash, signed, ends at 0)
 */
